package com.apexstreet.model;
import jakarta.persistence.*; import java.time.*;
@Entity @Table(name="automation_schedule_phases")
public class AutomationSchedulePhase { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="configuration_id",nullable=false) private AutomationConfiguration configuration; @Column(name="start_time",nullable=false) private LocalTime startTime; @Column(name="end_time",nullable=false) private LocalTime endTime; @Enumerated(EnumType.STRING) @Column(nullable=false,length=10) private AutomationAction action; @Column(nullable=false) private Integer brightness; @Enumerated(EnumType.STRING) @Column(name="week_type",nullable=false,length=15) private AutomationWeekType weekType; @Column(nullable=false) private Integer priority=0; @Column(name="phase_order",nullable=false) private Integer phaseOrder=0; @Column(name="created_at",nullable=false,updatable=false) private LocalDateTime createdAt; @Column(name="updated_at",nullable=false) private LocalDateTime updatedAt; @PrePersist void c(){var n=LocalDateTime.now();createdAt=n;updatedAt=n;} @PreUpdate void u(){updatedAt=LocalDateTime.now();} public Long getId(){return id;} public AutomationConfiguration getConfiguration(){return configuration;} public void setConfiguration(AutomationConfiguration v){configuration=v;} public LocalTime getStartTime(){return startTime;} public void setStartTime(LocalTime v){startTime=v;} public LocalTime getEndTime(){return endTime;} public void setEndTime(LocalTime v){endTime=v;} public AutomationAction getAction(){return action;} public void setAction(AutomationAction v){action=v;} public Integer getBrightness(){return brightness;} public void setBrightness(Integer v){brightness=v;} public AutomationWeekType getWeekType(){return weekType;} public void setWeekType(AutomationWeekType v){weekType=v;} public Integer getPriority(){return priority;} public void setPriority(Integer v){priority=v;} public Integer getPhaseOrder(){return phaseOrder;} public void setPhaseOrder(Integer v){phaseOrder=v;} }
